import numpy as np
import time

# _impute is now in selection.py — import it for backward compat
from .selection import _impute


def _add_mad_features(
    evaluator,
    feat_matrix: pd.DataFrame,
    paths,
    all_sample_ids: list[str],
    *,
    _echo=print,
) -> None:
    """Compute exact MAD features natively inside DuckDB via window functions.

    The entire MAD calculation runs as a single DuckDB query using CTEs:

    1. ``row_means``: compute ``list_avg()`` per row to get scalar means
    2. ``medians``: add per-(sample, region_type) median via window partition
    3. Final ``GROUP BY``: compute ``median(abs(row_mean - median))`` = MAD

    This returns only ~158 aggregated rows (one per sample × region_type),
    avoiding the previous approach that materialised ~446M row-level means
    in pandas (causing OOM on large cohorts like 14,898 samples).

    Modifies ``feat_matrix`` in-place, adding ``{rt}_{col}_mad`` columns.
    """
    from kreview.core import get_duckdb_conn, _discover_feature_paths

    array_cols = getattr(evaluator, "_array_cols", None)
    if not array_cols:
        return

    conn = get_duckdb_conn()
    file_paths = _discover_feature_paths(
        str(evaluator.source_file), paths.krewlyzer_dirs, set(all_sample_ids)
    )
    if not file_paths:
        log.warning("mad_no_files", evaluator=evaluator.name)
        return

    # ── Build DuckDB-native MAD query ──
    # CTE 1: per-row scalar means via list_avg()
    mean_exprs = ", ".join(f"list_avg({c}) AS {c}_row_mean" for c in array_cols)
    # CTE 2: per-(sample, region_type) median via window partition
    med_exprs = ", ".join(
        f"median({c}_row_mean) OVER (PARTITION BY sample_id, region_type)"
        f" AS med_{c}"
        for c in array_cols
    )
    # Final: MAD = median(|row_mean - median|)
    mad_exprs = ", ".join(
        f"median(abs({c}_row_mean - med_{c})) AS {c}_mad" for c in array_cols
    )
    pass_through = ", ".join(f"{c}_row_mean" for c in array_cols)

    query = f"""
        WITH row_means AS (
            SELECT
                regexp_extract(filename, '/([^/]+)/[^/]+$', 1) AS sample_id,
                REPLACE(REPLACE(REPLACE(CAST(region_type AS VARCHAR),
                    ' ', '_'), '-', '_'), '|', '_') AS region_type,
                {mean_exprs}
            FROM read_parquet(?, filename=true, union_by_name=true,
                              hive_partitioning=false)
            WHERE region_type IS NOT NULL
        ),
        medians AS (
            SELECT
                sample_id,
                region_type,
                {pass_through},
                {med_exprs}
            FROM row_means
        )
        SELECT
            sample_id,
            region_type,
            {mad_exprs}
        FROM medians
        GROUP BY sample_id, region_type
    """

    t_mad = time.time()
    try:
        mad_df = conn.execute(query, [file_paths]).df()
    except Exception as exc:
        log.warning("mad_query_failed", evaluator=evaluator.name, error=str(exc))
        _echo(f"  WARNING: MAD query failed ({exc}), MAD features omitted")
        return

    if mad_df.empty:
        log.warning("mad_query_empty", evaluator=evaluator.name)
        _echo("  WARNING: MAD query returned no rows, MAD features omitted")
        return

    log.debug(
        "mad_query_complete",
        evaluator=evaluator.name,
        n_rows=len(mad_df),
        elapsed_sec=round(time.time() - t_mad, 1),
    )

    # ── Pivot: sample_id × region_type → wide format ──
    id_col = "sample_id" if "sample_id" in feat_matrix.columns else "SAMPLE_ID"
    value_cols = [f"{c}_mad" for c in array_cols]
    pivoted = mad_df.pivot_table(
        index="sample_id",
        columns="region_type",
        values=value_cols,
        aggfunc="first",
    )
    # Flatten MultiIndex: (wps_nuc_mad, TSS) → TSS_wps_nuc_mad
    pivoted.columns = pd.Index(
        [f"{rt}_{col}" for col, rt in pivoted.columns]  # type: ignore[has-type]
    )
    pivoted = pivoted.reset_index()

    # ── Merge into feat_matrix in-place ──
    feat_matrix[id_col] = feat_matrix[id_col].astype(str)
    pivoted["sample_id"] = pivoted["sample_id"].astype(str)
    merged = pd.merge(
        feat_matrix,
        pivoted,
        left_on=id_col,
        right_on="sample_id",
        how="left",
    )
    if id_col != "sample_id" and "sample_id" in merged.columns:
        merged = merged.drop(columns=["sample_id"])

    for c in merged.columns:
        if c not in feat_matrix.columns:
            feat_matrix[c] = merged[c]

    mad_sec = time.time() - t_mad
    n_unique_mad = len([c for c in feat_matrix.columns if c.endswith("_mad")])
    _echo(f"  MAD computation: {n_unique_mad} features in {mad_sec:.1f}s")
    log.info(
        "mad_computed",
        evaluator=evaluator.name,
        n_mad_features=n_unique_mad,
        n_samples=len(pivoted),
        elapsed_sec=round(mad_sec, 1),
    )


def _extract_evaluator(
    evaluator,
    paths,
    all_sample_ids: list[str],
    chunk_size: int,
    out_path: Path,
    labels_df: pd.DataFrame,
    *,
    _echo=print,
) -> pd.DataFrame | None:
    """Extract features for a single evaluator and write the matrix parquet.

    Tries SQL pushdown first (Path A); falls back to chunked Python
    streaming (Path B) when the evaluator doesn't support SQL or SQL
    returns empty results.

    Returns:
        Merged DataFrame (labels + features) written to disk, or None
        if extraction produced no data.
    """
    from kreview.core import iter_feature_chunks, run_feature_sql

    _echo(f"  Extracting '{evaluator.name}'...")
    t1 = time.time()

    # --- Path A: SQL Pushdown (if evaluator supports it) ---
    sql_query = evaluator.extract_sql()
    feat_matrix = None

    if sql_query is not None:
        _echo(f"  Using SQL pushdown for '{evaluator.name}'...")
        sql_df = run_feature_sql(
            sql_query,
            str(evaluator.source_file),
            paths.krewlyzer_dirs,
            set(all_sample_ids),
        )
        if not sql_df.empty:
            extract_sec = time.time() - t1
            n_samples = (
                sql_df["sample_id"].nunique()
                if "sample_id" in sql_df.columns
                else len(sql_df)
            )

            # ── Multi-row SQL pivot (e.g. WPSGenome: sample × region_type) ──
            pivot_col = getattr(evaluator, "sql_pivot_column", None)
            if pivot_col and pivot_col in sql_df.columns:
                id_col = "sample_id"
                value_cols = [c for c in sql_df.columns if c not in (id_col, pivot_col)]
                pivoted = sql_df.pivot_table(
                    index=id_col,
                    columns=pivot_col,
                    values=value_cols,
                    aggfunc="first",
                )
                # Flatten MultiIndex: (wps_nuc_mean, TSS) → TSS_wps_nuc_mean
                col_tuples: list[tuple[str, str]] = list(pivoted.columns)
                pivoted.columns = [
                    f"{pivot_val}_{metric}" for metric, pivot_val in col_tuples
                ]
                feat_matrix = pivoted.reset_index()

                # ── Exact MAD via second DuckDB query ──
                _add_mad_features(
                    evaluator, feat_matrix, paths, all_sample_ids, _echo=_echo
                )

                feat_matrix = feat_matrix.rename(columns={"sample_id": "SAMPLE_ID"})
                _echo(
                    f"  SQL pushdown complete: {n_samples} samples, "
                    f"{len(feat_matrix.columns) - 1} features "
                    f"(pivoted on {pivot_col}) in {extract_sec:.1f}s"
                )
            else:
                # ── Single-row SQL (one row per sample, no pivot needed) ──
                feat_matrix = sql_df
                if (
                    "sample_id" in feat_matrix.columns
                    and "SAMPLE_ID" not in feat_matrix.columns
                ):
                    feat_matrix = feat_matrix.rename(columns={"sample_id": "SAMPLE_ID"})
                _echo(
                    f"  SQL pushdown complete: {n_samples} samples "
                    f"in {extract_sec:.1f}s"
                )
        else:
            _echo(
                f"  SQL pushdown returned empty result for '{evaluator.name}', "
                f"falling back to chunked extraction..."
            )
            sql_query = None  # Force fallback to Path B

    # --- Path B: Chunked Python streaming (default fallback) ---
    if sql_query is None:
        _echo(f"  Streaming cohort from DuckDB (chunk_size={chunk_size})...")
        partial_results = []
        failed_samples = []
        total_samples_processed = 0
        total_rows_read = 0

        for chunk_df, chunk_idx, n_chunks in iter_feature_chunks(
            str(evaluator.source_file),
            paths.krewlyzer_dirs,
            set(all_sample_ids),
            chunk_size=chunk_size,
            columns=getattr(evaluator, "extract_columns", None),
            target_rows=getattr(evaluator, "max_chunk_rows", 15_000_000),
        ):
            sid_col = "sample_id" if "sample_id" in chunk_df.columns else "SAMPLE_ID"
            chunk_sample_ids = chunk_df[sid_col].unique()
            chunk_n_rows = len(chunk_df)
            total_rows_read += chunk_n_rows

            _echo(
                f"  Chunk {chunk_idx + 1}/{n_chunks}: "
                f"{len(chunk_sample_ids)} samples, {chunk_n_rows:,} rows"
            )

            # Extract features from each sample within this chunk
            chunk_extracted = 0
            for sample_id in chunk_sample_ids:
                sample_df = chunk_df[chunk_df[sid_col] == sample_id]
                try:
                    res = evaluator.extract(sample_df)
                    if res:
                        res["SAMPLE_ID"] = sample_id
                        partial_results.append(pd.DataFrame([res]))
                        chunk_extracted += 1
                except Exception as exc:
                    log.warning(
                        "sample_extraction_failed",
                        evaluator=evaluator.name,
                        sample_id=sample_id,
                        error=str(exc),
                    )
                    failed_samples.append(sample_id)

            total_samples_processed += len(chunk_sample_ids)
            _echo(
                f"    Extracted {chunk_extracted}/" f"{len(chunk_sample_ids)} samples"
            )

            # Explicit memory release — reclaim ~5GB before next chunk
            del chunk_df

        if total_samples_processed == 0:
            _echo(f"  WARNING: No data found for {evaluator.name}, skipping")
            return None

        extract_sec = time.time() - t1
        _echo(
            f"  Extraction complete: {total_samples_processed} samples, "
            f"{total_rows_read:,} rows read in {extract_sec:.1f}s"
        )

        if failed_samples:
            failed_path = out_path / f"{evaluator.name}_failed_samples.csv"
            pd.DataFrame({"SAMPLE_ID": failed_samples}).to_csv(failed_path, index=False)
            _echo(
                f"  WARNING: {len(failed_samples)} samples failed extraction. "
                f"Saved to {failed_path.name}"
            )
            log.warning(
                "extraction_failures",
                evaluator=evaluator.name,
                n_failed=len(failed_samples),
                output=str(failed_path),
            )

        if not partial_results:
            _echo(f"  WARNING: No results for {evaluator.name}, skipping")
            return None

        feat_matrix = pd.concat(partial_results, ignore_index=True)

    # Guard: both Path A and Path B should set feat_matrix before reaching
    # this point (or return None). This is a safety net.
    if feat_matrix is None:
        _echo(f"  WARNING: No feature matrix produced for {evaluator.name}, skipping")
        return None

    merged = pd.merge(labels_df, feat_matrix, on="SAMPLE_ID", how="inner")
    out_p = out_path / f"{evaluator.name}_matrix.parquet"
    merged.to_parquet(out_p, index=False)
    _echo(f"  Matrix: {merged.shape[0]} samples x {merged.shape[1]} cols -> {out_p}")

    return merged


def _find_quarto() -> str:
    """Discover the quarto binary. With quarto-cli pip package, it's on PATH."""
    import shutil

    found = shutil.which("quarto")
    if found:
        return found
    # Fallback: check quarto-cli's known install location
    import importlib.util
    from pathlib import Path

    spec = importlib.util.find_spec("quarto")
    if spec and spec.origin:
        candidate = Path(spec.origin).parent / "bin" / "quarto"
        if candidate.is_file():
            return str(candidate)
    raise FileNotFoundError("Quarto not found. Install with: pip install quarto-cli")


def _render_quarto_report(
    matrix_path: str,
    feat_name: str,
    report_dir: Path,
    python_exe: str,
    cvd_safe: bool = False,
    shap_samples: int = 500,
    shap_features: int = 10,
    multimodal: bool = False,
) -> tuple[bool, str]:
    """Render a Quarto HTML dashboard for a single feature matrix.

    Quarto 1.9+ creates a ``.quarto/`` project directory next to the QMD
    source file.  When running inside a read-only Singularity container the
    installed package ``templates/`` directory is not writable, causing every
    render to fail with ``EROFS (error 30)``.  To work around this we copy
    all template assets into a writable *staging* directory under
    ``report_dir`` before invoking ``quarto render``.
    """
    import shutil
    import subprocess

    import structlog

    _log = structlog.get_logger()

    pkg_dir = Path(__file__).resolve().parent
    template_dir = pkg_dir / "templates"
    template_name = (
        "report_multimodal_template.qmd" if multimodal else "report_template.qmd"
    )
    template_file = template_dir / template_name

    if not template_file.exists():
        _log.error(
            "quarto_template_missing",
            template=str(template_file),
            multimodal=multimodal,
        )
        return False, f"Template not found at {template_file}"

    env = os.environ.copy()
    env["QUARTO_PYTHON"] = str(python_exe)

    quarto_bin = _find_quarto()
    out_html = Path(report_dir) / f"{feat_name}_dashboard.html"
    log_file = Path(report_dir) / f"{feat_name}_render.log"

    # ── Stage templates to a writable directory ──
    # Quarto 1.9+ creates a .quarto/ project directory next to the QMD file.
    # Inside read-only Singularity containers the package templates/ dir is
    # not writable.  Copy all template assets to a writable staging directory
    # so Quarto can create its project metadata without EROFS errors.
    staging_dir = Path(report_dir) / f".render_{feat_name}"
    staging_dir.mkdir(parents=True, exist_ok=True)
    for item in template_dir.iterdir():
        dest = staging_dir / item.name
        if item.is_file():
            shutil.copy2(item, dest)
        elif item.is_dir() and item.name != ".quarto":
            if dest.exists():
                shutil.rmtree(dest)
            shutil.copytree(item, dest)

    cmd = [
        quarto_bin,
        "render",
        template_name,
        "--log-level",
        "DEBUG",
        "-P",
        f"matrix_path:{Path(matrix_path).absolute()}",
        "-P",
        f"feature_name:{feat_name}",
        "-P",
        f"cvd_safe:{str(cvd_safe).lower()}",
        "-P",
        f"shap_samples:{shap_samples}",
        "-P",
        f"shap_features:{shap_features}",
        "--output",
        out_html.name,
        "--output-dir",
        str(out_html.parent.absolute()),
    ]

    try:
        subprocess.run(
            cmd,
            env=env,
            capture_output=True,
            text=True,
            check=True,
            timeout=600,
            cwd=str(staging_dir),  # writable staging dir, not read-only template_dir
        )
        shutil.rmtree(staging_dir, ignore_errors=True)
        return True, str(out_html)
    except subprocess.CalledProcessError as exc:
        # Write full output to disk for debugging
        with open(log_file, "w") as f:
            f.write(f"=== QUARTO RENDER DEBUG LOG: {feat_name} ===\n")
            f.write(f"CMD: {' '.join(cmd)}\n")
            f.write(f"CWD: {staging_dir}\n")
            f.write(f"EXIT CODE: {exc.returncode}\n\n")
            f.write("=== STDOUT ===\n")
            f.write(exc.stdout or "(empty)")
            f.write("\n\n=== STDERR ===\n")
            f.write(exc.stderr or "(empty)")
        # Return concise error + pointer to full log
        err_summary = f"Exit code {exc.returncode}. Full log: {log_file}\n"
        # Extract actual error lines (skip cell progress noise)
        for stream in [exc.stdout, exc.stderr]:
            if not stream:
                continue
            for line in stream.splitlines():
                line_s = line.strip()
                if any(
                    kw in line_s.lower()
                    for kw in [
                        "error",
                        "exception",
                        "traceback",
                        "failed",
                        "fatal",
                        "not found",
                    ]
                ):
                    err_summary += f"  >> {line_s}\n"
        _log.error(
            "quarto_render_failed",
            evaluator=feat_name,
            exit_code=exc.returncode,
            log_file=str(log_file),
        )
        shutil.rmtree(staging_dir, ignore_errors=True)
        return False, err_summary
    except subprocess.TimeoutExpired:
        _log.error("quarto_render_timeout", evaluator=feat_name, timeout_s=600)
        shutil.rmtree(staging_dir, ignore_errors=True)
        return False, "Timeout (>600s)"


